    """Clone a library repository.

    Args:
        url: URL of the remote to clone.
        dst_dir: Destination directory for the cloned repo.

    Raises:
        VersionControlError: Cloning the repository failed.
    """
    try:
        return git.Repo.clone_from(url, str(dst_dir), progress=ProgressReporter(name=url))
    except git.exc.GitCommandError as err:
        # Handle cases where stderr might be empty/None/whitespace
        stderr_msg = err.stderr if err.stderr else ""
        stderr_msg = stderr_msg.strip()
        if stderr_msg:
            error_detail = f" Error from VCS: {stderr_msg}"
        else:
            error_detail = " No additional error details from VCS."
        raise VersionControlError(f"Cloning git repository from url '{url}' failed.{error_detail}")

